object SecondThessaloniansData {
    val verses: List<Verse> = listOf(
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 1, text = "Mwen menm Pòl, ansanm ak Silven ak Timote, m'ap ekri lèt sa a voye bay manm legliz nan lavil Tesalonik k'ap viv ansanm nan Bondye, Papa a, ak Jezikri, Seyè nou an.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 2, text = "Mwen mande pou Bondye, Papa a, ak Jezikri, Seyè nou an, ban nou benediksyon ak kè poze.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 3, text = "Se yon devwa pou mwen pou m' pa janm sispann di Bondye mèsi pou nou, frè m' yo. Wi, se yon devwa pou m' fè l' vre. Paske, konfyans nou gen nan Bondye ap grandi anpil, renmen nou gen yonn pou lòt ap grandi toujou tou.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 4, text = "Se sak fè, sa fè m' plezi pou m' nonmen non nou nan tout legliz Bondye yo, pou jan nou gen pasyans, jan nou kenbe konfyans nou fèm nan Bondye nan mitan tout pèsekisyon ak soufrans k'ap tonbe sou nou.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 5, text = "Sa fè moun wè se Bondye ki gen rezon lè l'ap jije. Paske, avèk tou sa n'ap sipòte koulye a, n'ap fin bon nèt pou nou ka antre nan peyi kote Bondye wa a. Se pou peyi sa a menm n'ap soufri konsa.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 6, text = "Paske, Bondye gen pou fè sa ki byen: Bondye va gen rezon lè la fè moun k'ap fè nou soufri yo soufri tou.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 7, text = "Kanta pou nou menm k'ap soufri koulye a, la ban nou repo ansanm avè m' lè Jezi va parèt nan syèl la avèk zanj li yo ki gen pouvwa.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 8, text = "La parèt nan mitan gwo flanm dife pou peni tout moun ki pa konn Bondye yo ansanm ak moun ki p'ap mache dapre bon nouvèl ki pale sou Jezi, Seyè nou an.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 9, text = "Chatiman moun sa yo, se disparèt y'ap disparèt yo pou tout tan. Y'ap wete yo devan Seyè a, y'ap voye yo jete byen lwen pou yo pa janm resevwa pa yo nan pouvwa Seyè a ak nan lwanj y'ap fè pou li a.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 10, text = "Jou sa a, Seyè a va parèt pou l' resevwa lwanj nan men tout moun pa l' yo. Tout moun ki te mete konfyans yo nan li va kontan wè l'. Nou menm tou n'a wè li, paske nou te kwè nan mesaj mwen te fè nou konnen an.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 11, text = "Se poutèt sa, mwen p'ap janm sispann lapriyè pou nou. M'ap mande Bondye pou l' ede nou pou nou viv yon jan ki dakò ak lavi li mande nou pou nou viv la. M'ap mande l' pou li ban nou pouvwa li, pou nou ka fè tout byen nou vle fè, pou nou fin reyalize nèt travay n'ap fè ak konfyans nan Bondye.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 1, verseNumber = 12, text = "Konsa, tout moun va fè lwanj non Jezi a poutèt nou. Nou menm tou, y'a fè lwanj nou poutèt li, gremesi favè Bondye nou an ansanm ak Jezikri, Seyè a, fè nou. 2 Tesalonik", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 1, text = "Ann konsidere lè Jezikri, Seyè nou an, va parèt pou l' sanble nou ansanm bò kote li. Frè m' yo, men sa m'ap mande nou:", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 2, text = "Pa kite pesonn twouble lespri nou fasil, ni fè nou pèdi tèt nou ak ankenn mesaj ki swadizan soti nan Bondye, ni ak ankenn bèl diskou, ni ak ankenn lèt mwen ta swadizan ekri nou, pou yo fè nou kwè jou Seyè a rive deja.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 3, text = "Pa kite pesonn twonpe nou nan ankenn jan. Paske, anvan jou sa a rive, gen yon dènye revòlt kont Bondye ki pou fèt. Nou gen pou nou wè mechan ki deja kondannen pou disparèt la vini anvan.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 4, text = "Mechan sa a ap kanpe, l'ap pran pozisyon kont tout bagay lèzòm ap sèvi, kont tout bagay lèzòm konsidere pou Bondye. La fè, la fè, jouk la antre nan tanp Bondye a, la chita, la fè tèt li pase pou Bondye.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 5, text = "Nou pa chonje mwen te di nou sa lè m' te lakay nou toujou?", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 6, text = "Men, gen yon bagay k'ap anpeche levènman sa yo rive koulye a. Nou konnen kisa li ye: Se sak fè, mechan an p'ap parèt anvan lè li.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 7, text = "Wi, pouvwa mechan an deja ap travay anba chal. Men, anvan pou levènman sa yo rive, se pou moun k'ap ba l' baryè a disparèt.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 8, text = "Lè sa a, mechan an va parèt. Seyè Jezi va soufle ak bouch li sou li, la touye li. L'ap annik parèt nan tout pouvwa li pou l' fini nèt ak li.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 9, text = "Mechan an va vini ak tout pouvwa Satan an. Li va fè anpil mirak, anpil mèvèy ak anpil gwo siy pou bay manti.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 10, text = "Li va fè tout kalite bagay mal pou twonpe moun k'ap pèdi tèt yo. Y'ap pèdi tèt yo paske yo pa asepte verite ki pou ta sove yo a, yo pa renmen li.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 11, text = "Se poutèt sa, Bondye ap voye yon pouvwa k'ap travay pou egare yo pi rèd, pou yo sa kwè nan manti.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 12, text = "Konsa, tout moun ki p'ap kwè nan verite a, ki te pran plezi yo nan fè lenjistis, yo tout pral kondannen.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 13, text = "Se yon devwa pou mwen pou m' pa janm sispann di Bondye mèsi pou nou, frè m' yo, nou menm Seyè a renmen. Paske, Bondye chwazi nou pou nou ka premye moun ki pou delivre, gremesi pouvwa Sentespri ki fè nou tounen moun pa l', paske nou kwè nan verite a.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 14, text = "Gremesi bon nouvèl mwen te anonse nou an, Bondye chwazi nou pou nou ka resevwa pa nou nan lwanj ki pou Jezikri, Seyè nou an.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 15, text = "Se sa ki fè, frè m' yo, se pou nou kenbe fèm. Pa bliye tou sa nou te aprann nan bouch mwen ak nan lèt mwen an.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 16, text = "M'ap lapriyè Jezikri, Seyè nou an, ansanm ak Bondye, Papa nou ki renmen nou, ki fè nou favè, ki ban nou yon kouraj ki p'ap janm febli ansanm ak yon bèl espwa.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 2, verseNumber = 17, text = "M'ap mande yo pou yo fòtifye kè nou, pou yo ban nou fòs kouraj pou nou fè tou sa ki byen, pou nou di tou sa ki byen. 2 Tesalonik", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 1, text = "Pou fini, frè m' yo, lapriyè pou mwen pou pawòl Seyè a ka kontinye gaye toupatou byen vit, pou li resevwa lwanj tankou sa te fèt pami nou.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 2, text = "Lapriyè tou pou Bondye ka delivre m' anba move moun yo, mechan sa yo. Paske, se pa tout moun ki asepte kwè.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 3, text = "Men, Bondye ap toujou kenbe pawòl li. L'ap ban nou fòs, la pwoteje nou anba Satan.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 4, text = "Seyè a fè m' gen konfyans nan nou: li ban m' lasirans n'ap fè sa m' te mande nou fè a, epi n'ap toujou kontinye fè l' tou.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 5, text = "Mwen mande Seyè a pou l' dirije kè nou pou nou ka renmen Bondye, pou nou ka gen pasyans tankou Kris la.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 6, text = "Frè m' yo, men sa m'ap mande nou nan non Jezikri, Seyè a: Pran distans nou ak tout frè k'ap fè parese, ki p'ap konfòme yo ak sa m' te moutre nou.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 7, text = "Nou menm, nou konnen sa pou nou fè pou nou ka swiv egzanp mwen ban nou. Mwen pa t' fè parese lè m' te nan mitan nou.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 8, text = "Mwen pa t' kite pesonn ban m' manje pou gremesi. Okontrè, mwen te travay di, mwen te fatige kò mwen anpil, lajounen kou lannwit, pou m' pa t' sou kont nou yonn.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 9, text = "Se pa paske mwen pa t' gen dwa resevwa anyen nan men pesonn ki fè m' te fè sa. Non. Se paske mwen te vle ban nou yon egzanp pou nou te swiv.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 10, text = "Nou chonje lè m' te lakay nou, mwen te di nou: moun ki pa travay pa gen dwa manje non plis.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 11, text = "M'ap pale konsa ak nou paske m' pran nouvèl gen kèk moun nan mitan nou k'ap fè parese, ki pa vle fè lòt bagay pase foure bouch yo nan zafè lòt moun.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 12, text = "Men sa m'ap voye di moun sa yo: Nan non Jezikri, Seyè a, m'ap mande nou pou nou travay nan lòd, pou nou manje swe kouraj nou.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 13, text = "Pou nou menm, frè m' yo, pa janm bouke fè sa ki byen.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 14, text = "Si yon moun pa swiv lòd mwen bay nan lèt sa a, make li. Piga pesonn gen okenn rapò avè l', pou l' sa wont.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 15, text = "Men, se pa poutèt sa pou nou fè lènmi avè li. Okontrè, pale avè l' tankou yon frè.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 16, text = "Mwen mande Seyè a ki konn bay kè poze, pou li fè kè nou poze tout tan, tout jan, pou li toujou la avèk nou tout.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 17, text = "Se mwen menm Pòl k'ap ekri mo sa yo: mwen voye bonjou pou nou tout. Se konsa mwen siyen tout lèt mwen yo, se konsa mwen toujou ekri.", bookId = 53),
        Verse(book = "2 Tesalonisyen", chapter = 3, verseNumber = 18, text = "Se pou benediksyon Jezikri, Seyè nou an, toujou la avèk nou tout. 2 Tesalonik", bookId = 53)
